from __future__ import annotations

"""Checkout.session.completed handling before your OMS drops a pick list."""

from fulfillment_ledger import FulfillmentLedger
from stripe_checkout_models import (
    STATUS_COMPLETE,
    CheckoutSessionCompletedPayload,
)


REASON_DISPATCHED = "dispatched"
REASON_REPLAY_SKIPPED = "replay_skipped"
REASON_NOT_COMPLETE = "checkout_not_complete"


def _checkout_is_complete(payload: CheckoutSessionCompletedPayload) -> bool:
    return payload.status.casefold() == STATUS_COMPLETE.casefold()


def evaluate_checkout_fulfillment(
    payload: CheckoutSessionCompletedPayload,
    ledger: FulfillmentLedger,
) -> dict[str, object]:
    """Apply webhook payload to the fulfillment ledger (single evaluation)."""
    if not _checkout_is_complete(payload):
        return {
            "checkout_session_id": payload.checkout_session_id,
            "stripe_event_id": payload.stripe_event_id,
            "fulfillment_dispatched": False,
            "duplicate_webhook": False,
            "shipment_id": None,
            "reason": REASON_NOT_COMPLETE,
            "ledger_shipment_total": ledger.shipment_count(),
        }

    shipment_id = ledger.dispatch_from_checkout(payload)
    return {
        "checkout_session_id": payload.checkout_session_id,
        "stripe_event_id": payload.stripe_event_id,
        "fulfillment_dispatched": True,
        "duplicate_webhook": False,
        "shipment_id": shipment_id,
        "reason": REASON_DISPATCHED,
        "ledger_shipment_total": ledger.shipment_count(),
    }


def summarize_checkout_fulfillments(results: list[dict[str, object]]) -> dict[str, object]:
    dispatched = sum(1 for row in results if row.get("fulfillment_dispatched"))
    replays = sum(1 for row in results if row.get("duplicate_webhook"))
    blocked = sum(1 for row in results if row.get("reason") == REASON_NOT_COMPLETE)
    return {
        "events_evaluated": len(results),
        "dispatch_count": dispatched,
        "replay_skip_count": replays,
        "incomplete_count": blocked,
        "results": results,
    }


class CheckoutFulfillmentWorkflow:
    """Stateful worker used by the HTTP handler in integration tests."""

    def __init__(self, ledger: FulfillmentLedger | None = None) -> None:
        self._ledger = ledger if ledger is not None else FulfillmentLedger()
        self._history: list[dict[str, object]] = []

    @property
    def ledger(self) -> FulfillmentLedger:
        return self._ledger

    def handle(self, payload: CheckoutSessionCompletedPayload) -> dict[str, object]:
        outcome = evaluate_checkout_fulfillment(payload, self._ledger)
        self._history.append(outcome)
        return outcome

    def summarize(self) -> dict[str, object]:
        return summarize_checkout_fulfillments(self._history)

    def history(self) -> list[dict[str, object]]:
        return list(self._history)


def workflow_ops_snapshot(workflow: CheckoutFulfillmentWorkflow) -> str:
    summary = workflow.summarize()
    if summary["dispatch_count"] and summary["replay_skip_count"]:
        return "steady_with_replays"
    if summary["dispatch_count"]:
        return "dispatching"
    if summary["incomplete_count"]:
        return "blocked"
    return "idle"

