from __future__ import annotations

import uuid
from dataclasses import dataclass, field

from stripe_checkout_models import CheckoutSessionCompletedPayload


@dataclass
class ShipmentRecord:
    shipment_id: str
    checkout_session_id: str
    stripe_event_id: str
    customer_email: str
    units: int


@dataclass
class FulfillmentLedger:
    """In-memory 3PL handoff log used by the webhook worker in tests."""

    _shipments: list[ShipmentRecord] = field(default_factory=list)
    _processed_event_ids: set[str] = field(default_factory=set)

    def shipment_count(self) -> int:
        return len(self._shipments)

    def has_processed_event(self, stripe_event_id: str) -> bool:
        return stripe_event_id in self._processed_event_ids

    def mark_event_processed(self, stripe_event_id: str) -> None:
        self._processed_event_ids.add(stripe_event_id.strip())

    def last_shipment_id(self) -> str | None:
        if not self._shipments:
            return None
        return self._shipments[-1].shipment_id

    def shipment_id_for_event(self, stripe_event_id: str) -> str | None:
        needle = stripe_event_id.strip()
        for row in reversed(self._shipments):
            if row.stripe_event_id == needle:
                return row.shipment_id
        return None

    def record_shipment(
        self,
        *,
        checkout_session_id: str,
        stripe_event_id: str,
        customer_email: str,
        units: int,
        preferred_shipment_id: str | None = None,
    ) -> str:
        ship_id = preferred_shipment_id or f"ship_{uuid.uuid4().hex[:12]}"
        row = ShipmentRecord(
            shipment_id=ship_id,
            checkout_session_id=checkout_session_id.strip(),
            stripe_event_id=stripe_event_id.strip(),
            customer_email=customer_email.strip(),
            units=units,
        )
        self._shipments.append(row)
        return ship_id

    def dispatch_from_checkout(self, payload: CheckoutSessionCompletedPayload) -> str:
        """Create a carrier pick ticket from a completed Checkout session."""
        units = payload.units_shippable()
        return self.record_shipment(
            checkout_session_id=payload.checkout_session_id,
            stripe_event_id=payload.stripe_event_id,
            customer_email=payload.customer_email,
            units=units,
        )

    def total_units_shipped(self) -> int:
        return sum(row.units for row in self._shipments)

    def export_audit_rows(self) -> list[dict[str, object]]:
        return [
            {
                "shipment_id": row.shipment_id,
                "checkout_session_id": row.checkout_session_id,
                "stripe_event_id": row.stripe_event_id,
                "units": row.units,
            }
            for row in self._shipments
        ]


def reconcile_ledger_rows(ledger: FulfillmentLedger) -> dict[str, object]:
    rows = ledger.export_audit_rows()
    session_ids = {str(r["checkout_session_id"]) for r in rows}
    return {
        "row_count": len(rows),
        "distinct_sessions": len(session_ids),
        "total_units": ledger.total_units_shipped(),
    }

