from __future__ import annotations

from dataclasses import dataclass


CHECKOUT_MODE_PAYMENT = "payment"
CHECKOUT_MODE_SUBSCRIPTION = "subscription"

STATUS_COMPLETE = "complete"


def _require(label: str, value: str | None) -> str:
    if value is None or not str(value).strip():
        raise ValueError(f"{label} is required")
    return str(value).strip()


@dataclass(frozen=True)
class CheckoutLineItem:
    sku: str
    quantity: int

    def __post_init__(self) -> None:
        sku = _require("sku", self.sku)
        if self.quantity < 1:
            raise ValueError("quantity must be at least 1")
        object.__setattr__(self, "sku", sku)


@dataclass(frozen=True)
class CheckoutSessionCompletedPayload:
    """Shape your worker normalizes from Stripe checkout.session.completed."""

    stripe_event_id: str
    checkout_session_id: str
    customer_email: str
    payment_intent_id: str | None
    mode: str
    status: str
    amount_total_cents: int
    currency: str
    client_reference_id: str | None
    line_items: tuple[CheckoutLineItem, ...]

    def __post_init__(self) -> None:
        event_id = _require("stripe_event_id", self.stripe_event_id)
        session_id = _require("checkout_session_id", self.checkout_session_id)
        email = _require("customer_email", self.customer_email)
        mode = _require("mode", self.mode)
        status = _require("status", self.status)
        currency = _require("currency", self.currency).lower()
        if len(currency) != 3:
            raise ValueError("currency must be a 3-letter code")
        if self.amount_total_cents < 0:
            raise ValueError("amount_total_cents must be non-negative")
        if mode not in {CHECKOUT_MODE_PAYMENT, CHECKOUT_MODE_SUBSCRIPTION}:
            raise ValueError("unsupported checkout mode")
        if not self.line_items:
            raise ValueError("line_items must not be empty")
        object.__setattr__(self, "stripe_event_id", event_id)
        object.__setattr__(self, "checkout_session_id", session_id)
        object.__setattr__(self, "customer_email", email)
        object.__setattr__(self, "mode", mode)
        object.__setattr__(self, "status", status)
        object.__setattr__(self, "currency", currency)

    def fulfillment_customer_key(self) -> str:
        base = self.customer_email.lower().strip()
        ref = (self.client_reference_id or "").strip()
        return f"{base}|{ref}"

    def units_shippable(self) -> int:
        return sum(item.quantity for item in self.line_items)


def describe_payment_instrument(payload: CheckoutSessionCompletedPayload) -> str:
    if payload.payment_intent_id:
        return f"pi:{payload.payment_intent_id.strip()}"
    return "no_pi"


def line_items_signature(items: tuple[CheckoutLineItem, ...]) -> str:
    parts = [f"{item.sku}:{item.quantity}" for item in items]
    return "|".join(sorted(parts))


def session_summary_line(payload: CheckoutSessionCompletedPayload) -> str:
    pi = describe_payment_instrument(payload)
    return (
        f"{payload.checkout_session_id} {payload.amount_total_cents} "
        f"{payload.currency} customer={payload.customer_email} {pi}"
    )

